class Settings(BaseSettings):
    model_config = SettingsConfigDict(
        # App config lives in .env.app; the root .env is compose/infra-only and NOT read here — the
        # split keeps infra keys from tripping extra=forbid (#209).
        env_file=".env.app",
        env_file_encoding="utf-8",
        extra="forbid",
        case_sensitive=False,
    )

    environment: Literal["dev", "staging", "prod"] = "dev"
    log_level: Literal["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"] = "INFO"

    # Real URL (with password) comes from the environment; this default is only a credential-less
    # placeholder for the no-env case.
    database_url: str = Field(default="postgresql+psycopg2://localhost:5432/dataq")
    redis_url: str = Field(default="redis://localhost:6379/0")

    applicationinsights_connection_string: str | None = None

    # Generic OTLP/HTTP exporter endpoint (#589), base-endpoint semantics; may be set alongside the
    # Azure exporter.
    otel_exporter_otlp_endpoint: str | None = None

    # OpenLineage emission (ADR 0034, #758) — dark by default.
    openlineage_url: str | None = None
    openlineage_disabled: bool = False

    # Lineage catalog pull (ADR 0034, #762) — dark by default; only `marquez` is implemented.
    lineage_provider: str = ""
    marquez_url: str | None = None

    # Warehouse-native lineage pull (ADR 0034, #858) — on by default (asset-first: lineage is a
    # baseline capability, not an add-on). Queries ACCOUNT_USAGE / system.access; set false if the
    # principal lacks those grants and the daily refresh should no-op instead of erroring per run.
    warehouse_lineage_enabled: bool = True

    # Classification propagation through column lineage (#1710): a column whose recorded upstream
    # column is tagged sensitive is masked too. Additive-only (never un-masks); false opts out.
    lineage_classification_propagation: bool = True

    # Snowflake GET_LINEAGE seeds walked per refresh (#892) — a latency/cost bound.
    warehouse_lineage_max_seeds: int = 500
    # COLUMN-domain GET_LINEAGE seeds per refresh (#2106): one call per column of each edge whose
    # column grain nothing else recorded (views and dynamic tables). 0 disables the pass.
    warehouse_lineage_max_column_seeds: int = Field(default=300, ge=0)

