    try:
        name = UsageEvent(event)
    except ValueError:
        raise UsageEventInvalid("unknown usage event") from None
    spec = EVENTS[name]
    out: dict[str, Any] = {}
    for key, value in attributes.items():
        vocabulary = spec.get(key)
        if vocabulary is None:
            raise UsageEventInvalid(f"{name.value}: attribute {key!r} is not in the vocabulary")
        if not vocabulary.allows(value):
            raise UsageEventInvalid(f"{name.value}: attribute {key!r} has a value outside its vocabulary")
